    let sql = "SELECT percentile_cont(0.5::float8) WITHIN GROUP(ORDER BY x) FILTER (WHERE x <= 2) AS c, count(*) AS n FROM (VALUES(1::float8),(2::float8),(9::float8)) t(x)";
